// Coresignal search endpoints return a bare array of IDs, which n8n splits into one item per ID.
// Flatten whatever shape arrives, dedupe, cap at max_jobs, emit one item per job ID.
const cfg = $('Set Search Parameters').first().json;
const max = Number(cfg.max_jobs) || 10;

let ids = [];
for (const it of $input.all()) {
  const j = it.json;
  if (typeof j === 'number' || (typeof j === 'string' && j)) {
    ids.push(j);
  } else if (Array.isArray(j)) {
    ids = ids.concat(j);
  } else if (j && typeof j === 'object') {
    if (Array.isArray(j.body)) ids = ids.concat(j.body);
    else if (Array.isArray(j.data)) ids = ids.concat(j.data);
    else ids = ids.concat(Object.values(j));
  }
}

ids = ids
  .filter(v => typeof v === 'number' || (typeof v === 'string' && String(v).trim() !== ''))
  .map(v => String(v));
ids = [...new Set(ids)].slice(0, max);

if (!ids.length) return [];
return ids.map(id => ({ json: { job_id: id } }));

// Flatten the Coresignal job record into the fields the digest needs.
const j = $json || {};

const val = (o, keys) => {
  for (const k of keys) {
    if (o && o[k] !== undefined && o[k] !== null && o[k] !== '') return o[k];
  }
  return '';
};

const sources = Array.isArray(j.job_sources) ? j.job_sources : [];
const srcUrl = sources.length ? val(sources[0], ['url']) : '';
const locParts = [val(j, ['city']), val(j, ['state']), val(j, ['country'])].filter(Boolean);

return {
  job_id: String(val(j, ['id', 'job_id'])),
  job_title: val(j, ['title']),
  job_url: srcUrl || val(j, ['external_url']),
  job_seniority: val(j, ['seniority']),
  job_department: val(j, ['department']),
  employment_type: val(j, ['employment_type']),
  job_location: val(j, ['location']) || locParts.join(', '),
  posted_at: String(val(j, ['date_posted', 'created_at', 'updated_at'])).slice(0, 10),
  company_name: val(j, ['company_name']),
  company_domain: val(j, ['company_domain']),
  company_industry: val(j, ['company_industry']),
  company_employees_count: val(j, ['company_employees_count'])
};

// Employee search returns a bare array of IDs ordered by _score — keep the top one.
let ids = [];
for (const it of $input.all()) {
  const j = it.json;
  if (typeof j === 'number' || (typeof j === 'string' && j)) {
    ids.push(j);
  } else if (Array.isArray(j)) {
    ids = ids.concat(j);
  } else if (j && typeof j === 'object') {
    if (Array.isArray(j.body)) ids = ids.concat(j.body);
    else if (Array.isArray(j.data)) ids = ids.concat(j.data);
    else ids = ids.concat(Object.values(j));
  }
}

ids = ids.filter(v => typeof v === 'number' || (typeof v === 'string' && String(v).trim() !== ''));

return [{ json: { hr_employee_id: ids.length ? String(ids[0]) : '' } }];

// Merge the job record with the HR profile into one flat digest row.
const job = $('Prepare Job Record').first().json;
const c = $json || {};

const val = (o, keys) => {
  for (const k of keys) {
    if (o && o[k] !== undefined && o[k] !== null && o[k] !== '') return o[k];
  }
  return '';
};

const pickEmail = (p, key) => {
  const coll = p && p.professional_emails_collection;
  if (!Array.isArray(coll) || !coll.length) return '';
  const sorted = coll.slice().sort((a, b) => (a.order_of_priority ?? 99) - (b.order_of_priority ?? 99));
  return sorted[0][key] || '';
};

const email = val(c, ['primary_professional_email', 'professional_email']) || pickEmail(c, 'professional_email');
const emailStatus = val(c, ['primary_professional_email_status']) || pickEmail(c, 'professional_email_status');
const name = val(c, ['full_name', 'name']);

return {
  ...job,
  hr_found: !!name,
  hr_name: name,
  hr_title: val(c, ['active_experience_title', 'headline', 'job_title']),
  hr_department: val(c, ['active_experience_department']),
  hr_management_level: val(c, ['active_experience_management_level']),
  hr_location: val(c, ['location_full', 'location_country']),
  hr_linkedin: val(c, ['linkedin_url', 'professional_network_url', 'url']),
  hr_email: email,
  hr_email_status: emailStatus,
  hr_coresignal_id: String(val(c, ['id']))
};

// Reached when there is no company domain, no company match, or no HR profile.
// The job still goes into the digest, just without a contact.
const job = $('Prepare Job Record').first().json;

return {
  ...job,
  hr_found: false,
  hr_name: '',
  hr_title: '',
  hr_department: '',
  hr_management_level: '',
  hr_location: '',
  hr_linkedin: '',
  hr_email: '',
  hr_email_status: '',
  hr_coresignal_id: ''
};

// Build one Slack Block Kit digest from every job row collected by the loop.
const cfg = $('Set Search Parameters').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.job_title);

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const link = (url, label) => (url ? `<${url}|${esc(label)}>` : esc(label));

const periodStart = $now.minus({ days: Number(cfg.days_back) || 7 }).toFormat('d LLL');
const periodEnd = $now.toFormat('d LLL yyyy');
const withHr = rows.filter(r => r.hr_found).length;

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: `Weekly job digest — ${rows.length} new roles`, emoji: false }
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `*${periodStart} – ${periodEnd}*  ·  ${esc(cfg.country)}  ·  HR contact found for ${withHr}/${rows.length}`
      }
    ]
  },
  { type: 'divider' }
];

const textLines = [`Weekly job digest — ${rows.length} new roles (${periodStart} – ${periodEnd})`, ''];

rows.forEach((r, i) => {
  const meta = [r.job_location, r.job_seniority, r.employment_type, r.posted_at ? `posted ${r.posted_at}` : '']
    .filter(Boolean)
    .map(esc)
    .join('  ·  ');

  let hrLine;
  if (r.hr_found) {
    const parts = [`*${esc(r.hr_name)}*`];
    if (r.hr_title) parts.push(esc(r.hr_title));
    if (r.hr_linkedin) parts.push(link(r.hr_linkedin, 'profile'));
    if (r.hr_email) parts.push(esc(r.hr_email));
    hrLine = `HR contact: ${parts.join('  ·  ')}`;
  } else {
    hrLine = '_No HR contact found for this company_';
  }

  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${i + 1}. ${link(r.job_url, r.job_title || 'Untitled role')}*  —  ${esc(r.company_name)}\n${meta}\n${hrLine}`
    }
  });

  textLines.push(`${i + 1}. ${r.job_title} — ${r.company_name} (${r.job_location || 'n/a'})`);
  textLines.push(`   ${r.job_url || 'no url'}`);
  textLines.push(`   HR: ${r.hr_found ? `${r.hr_name}, ${r.hr_title} ${r.hr_email || ''}` : 'not found'}`);
});

if (!rows.length) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: '_No matching job ads were posted in this period._' }
  });
  textLines.push('No matching job ads were posted in this period.');
}

blocks.push({ type: 'divider' });
blocks.push({
  type: 'context',
  elements: [{ type: 'mrkdwn', text: 'Source: Coresignal multi-source jobs & employees' }]
});

return [{
  json: {
    blocks,
    digest_text: textLines.join('\n'),
    notification_text: `Weekly job digest — ${rows.length} new roles, ${withHr} with an HR contact`,
    job_count: rows.length,
    hr_found_count: withHr,
    slack_channel: cfg.slack_channel,
    rows
  }
}];
